@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="settings-sidebar">
    <nav class="nav nav-pills flex-column gap-1">
        @foreach (var section in Sections)
        {
            <button class="nav-link text-start @(ActiveSection == section ? "active" : "")"
                    @onclick="() => OnSectionChanged.InvokeAsync(section)">
                <span class="sidebar-icon">@GetIcon(section)</span>
                @section
            </button>
        }
    </nav>
</div>

@code {
    private static readonly string[] Sections = ["Profile", "Notifications", "Security", "Appearance"];

    [Parameter, EditorRequired]
    public string ActiveSection { get; set; } = "Profile";

    [Parameter, EditorRequired]
    public EventCallback<string> OnSectionChanged { get; set; }

    private static string GetIcon(string section) => section switch
    {
        "Profile" => "👤",
        "Notifications" => "🔔",
        "Security" => "🔒",
        "Appearance" => "🎨",
        _ => "⚙️"
    };
}

.settings-sidebar {
    min-width: 200px;
    padding: 1rem;
    border-right: 1px solid var(--bs-border-color);
    background-color: var(--bs-body-bg);
}

.settings-sidebar .nav-link {
    color: var(--bs-body-color);
    border-radius: 0.375rem;
    padding: 0.6rem 1rem;
    font-weight: 500;
    cursor: pointer;
    border: none;
    background: none;
    width: 100%;
}

.settings-sidebar .nav-link:hover:not(.active) {
    background-color: var(--bs-tertiary-bg);
}

.settings-sidebar .nav-link.active {
    background-color: var(--bs-primary);
    color: #fff;
}

.sidebar-icon {
    margin-right: 0.5rem;
}

@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="change-password-panel">
    <button class="btn btn-outline-secondary w-100 text-start d-flex justify-content-between align-items-center"
            @onclick="ToggleExpanded">
        <span>Change Password</span>
        <span>@(isExpanded ? "▲" : "▼")</span>
    </button>

    @if (isExpanded)
    {
        <div class="mt-3 p-3 border rounded">
            <div class="mb-3">
                <label class="form-label">Current Password</label>
                <input type="password" class="form-control" @bind="currentPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">New Password</label>
                <input type="password" class="form-control" @bind="newPassword" />
            </div>
            <div class="mb-3">
                <label class="form-label">Confirm New Password</label>
                <input type="password" class="form-control" @bind="confirmPassword"
                       class="form-control @(HasMismatch ? "is-invalid" : "")" />
                @if (HasMismatch)
                {
                    <div class="invalid-feedback">Passwords do not match.</div>
                }
            </div>

            @if (!string.IsNullOrEmpty(message))
            {
                <div class="alert @(isError ? "alert-danger" : "alert-success") py-2">@message</div>
            }

            <button class="btn btn-primary" @onclick="UpdatePassword" disabled="@isSaving">
                @if (isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Update Password
            </button>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public EventCallback<(string CurrentPassword, string NewPassword)> OnChangePassword { get; set; }

    private bool isExpanded;
    private string currentPassword = "";
    private string newPassword = "";
    private string confirmPassword = "";
    private string? message;
    private bool isError;
    private bool isSaving;

    private bool HasMismatch =>
        !string.IsNullOrEmpty(confirmPassword) && confirmPassword != newPassword;

    private void ToggleExpanded() => isExpanded = !isExpanded;

    private async Task UpdatePassword()
    {
        message = null;

        if (string.IsNullOrWhiteSpace(currentPassword) ||
            string.IsNullOrWhiteSpace(newPassword))
        {
            message = "All password fields are required.";
            isError = true;
            return;
        }

        if (HasMismatch)
        {
            message = "Passwords do not match.";
            isError = true;
            return;
        }

        isSaving = true;
        try
        {
            await OnChangePassword.InvokeAsync((currentPassword, newPassword));
            message = "Password updated successfully.";
            isError = false;
            currentPassword = "";
            newPassword = "";
            confirmPassword = "";
        }
        catch (Exception ex)
        {
            message = $"Failed to update password: {ex.Message}";
            isError = true;
        }
        finally
        {
            isSaving = false;
        }
    }
}

@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="active-sessions-table">
    <h6>Active Sessions</h6>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-sm table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    @if (confirmingSessionId == session.Id)
