@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="active-sessions-table">
    <h6>Active Sessions</h6>

    @if (Sessions is null || Sessions.Count == 0)
    {
        <p class="text-muted">No active sessions.</p>
    }
    else
    {
        <div class="table-responsive">
            <table class="table table-sm table-hover">
                <thead>
                    <tr>
                        <th>Device</th>
                        <th>Location</th>
                        <th>Last Active</th>
                        <th></th>
                    </tr>
                </thead>
                <tbody>
                    @foreach (var session in Sessions)
                    {
                        <tr>
                            <td>@session.Device</td>
                            <td>@session.Location</td>
                            <td>@session.LastActive.ToString("g")</td>
                            <td>
                                @if (session.Id != CurrentSessionId)
                                {
                                    @if (confirmingSessionId == session.Id)
                                    {
                                        <span class="d-inline-flex gap-1 align-items-center">
                                            <span class="text-danger small">Revoke?</span>
                                            <button class="btn btn-danger btn-sm"
                                                    @onclick="() => ConfirmRevoke(session.Id)"
                                                    disabled="@isRevoking">
                                                Yes
                                            </button>
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    @onclick="CancelRevoke">
                                                No
                                            </button>
                                        </span>
                                    }
                                    else
                                    {
                                        <button class="btn btn-outline-danger btn-sm"
                                                @onclick="() => RequestRevoke(session.Id)">
                                            Revoke
                                        </button>
                                    }
                                }
                                else
                                {
                                    <span class="badge bg-success">Current</span>
                                }
                            </td>
                        </tr>
                    }
                </tbody>
            </table>
        </div>
    }
</div>

@code {
    [Parameter, EditorRequired]
    public List<ActiveSession> Sessions { get; set; } = [];

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }

    private string? confirmingSessionId;
    private bool isRevoking;

    private void RequestRevoke(string sessionId) => confirmingSessionId = sessionId;

    private void CancelRevoke() => confirmingSessionId = null;

    private async Task ConfirmRevoke(string sessionId)
    {
        isRevoking = true;
        try
        {
            await OnRevokeSession.InvokeAsync(sessionId);
            confirmingSessionId = null;
        }
        finally
        {
            isRevoking = false;
        }
    }
}

