arguments.file_text:
@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="profile-section">
    <h4 class="mb-4">Profile Settings</h4>

    <div class="row">
        <div class="col-md-8">
            <div class="mb-3">
                <label class="form-label">Display Name</label>
                <input type="text" class="form-control" @bind="displayName" />
            </div>
            <div class="mb-3">
                <label class="form-label">Email</label>
                <input type="email" class="form-control" @bind="email" />
            </div>
            <div class="mb-3">
                <label class="form-label">Bio</label>
                <textarea class="form-control" rows="4" @bind="bio"></textarea>
            </div>
        </div>
        <div class="col-md-4">
            <div class="avatar-preview text-center">
                <label class="form-label">Avatar Preview</label>
                @if (!string.IsNullOrWhiteSpace(avatarUrl))
                {
                    <div class="mb-2">
                        <img src="@avatarUrl" alt="Avatar" class="rounded-circle img-thumbnail"
                             style="width: 120px; height: 120px; object-fit: cover;" />
                    </div>
                }
                else
                {
                    <div class="mb-2 rounded-circle bg-secondary d-inline-flex align-items-center justify-content-center"
                         style="width: 120px; height: 120px;">
                        <span class="text-white fs-1">👤</span>
                    </div>
                }
                <div class="small text-muted text-break">@avatarUrl</div>
            </div>
        </div>
    </div>

    @if (!string.IsNullOrEmpty(message))
    {
        <div class="alert alert-success py-2 mt-2">@message</div>
    }

    <div class="d-flex gap-2 mt-3">
        <button class="btn btn-primary" @onclick="SaveChanges" disabled="@isSaving">
            @if (isSaving)
            {
                <span class="spinner-border spinner-border-sm me-1"></span>
            }
            Save Changes
        </button>
        <button class="btn btn-outline-secondary" @onclick="DiscardChanges" disabled="@(!HasChanges)">
            Discard Changes
        </button>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public UserProfile Profile { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<UserProfile> OnSave { get; set; }

    private string displayName = "";
    private string email = "";
    private string avatarUrl = "";
    private string bio = "";
    private string? message;
    private bool isSaving;

    private bool HasChanges =>
        displayName != Profile.DisplayName ||
        email != Profile.Email ||
        bio != Profile.Bio;

    protected override void OnParametersSet()
    {
        if (displayName == "" && Profile is not null)
        {
            CopyFromProfile();
        }
    }

    private void CopyFromProfile()
    {
        displayName = Profile.DisplayName;
        email = Profile.Email;
        avatarUrl = Profile.AvatarUrl;
        bio = Profile.Bio;
        message = null;
    }

    private async Task SaveChanges()
    {
        isSaving = true;
        message = null;
        try
        {
            var updated = Profile with
            {
                DisplayName = displayName,
                Email = email,
                AvatarUrl = avatarUrl,
                Bio = bio
            };
            await OnSave.InvokeAsync(updated);
            message = "Profile saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }

    private void DiscardChanges()
    {
        CopyFromProfile();
    }
}

@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="notifications-section">
    <h4 class="mb-4">Notification Preferences</h4>

    <div class="mb-4">
        <h6>General</h6>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="emailNotif" @bind="emailNotifications" />
            <label class="form-check-label" for="emailNotif">Email Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="pushNotif" @bind="pushNotifications" />
            <label class="form-check-label" for="pushNotif">Push Notifications</label>
        </div>
        <div class="form-check form-switch mb-2">
            <input class="form-check-input" type="checkbox" id="weeklyDigest" @bind="weeklyDigest" />
            <label class="form-check-label" for="weeklyDigest">Weekly Digest</label>
        </div>
    </div>

    <div class="mb-4">
        <h6>Muted Channels</h6>
        @if (AvailableChannels.Count == 0)
        {
            <p class="text-muted">No channels available.</p>
        }
        else
        {
            @foreach (var channel in AvailableChannels)
            {
                var isMuted = mutedChannels.Contains(channel);
                <div class="form-check mb-1">
                    <input class="form-check-input" type="checkbox" id="@($"ch-{channel}")"
                           checked="@isMuted"
                           @onchange="e => ToggleChannel(channel, (bool)(e.Value ?? false))" />
                    <label class="form-check-label" for="@($"ch-{channel}")">@channel</label>
                </div>
            }
        }
    </div>

    @if (!string.IsNullOrEmpty(message))
    {
        <div class="alert alert-success py-2">@message</div>
    }

    <button class="btn btn-primary" @onclick="SavePreferences" disabled="@isSaving">
        @if (isSaving)
        {
            <span class="spinner-border spinner-border-sm me-1"></span>
        }
        Save Preferences
    </button>
</div>

@code {
    [Parameter, EditorRequired]
    public NotificationPrefs Prefs { get; set; } = default!;

    [Parameter]
    public List<string> AvailableChannels { get; set; } = ["General", "Announcements", "Updates", "Marketing", "Support"];

    [Parameter, EditorRequired]
    public EventCallback<NotificationPrefs> OnSave { get; set; }

    private bool emailNotifications;
    private bool pushNotifications;
    private bool weeklyDigest;
    private HashSet<string> mutedChannels = [];
    private string? message;
    private bool isSaving;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (!initialized && Prefs is not null)
        {
            emailNotifications = Prefs.EmailNotifications;
            pushNotifications = Prefs.PushNotifications;
            weeklyDigest = Prefs.WeeklyDigest;
            mutedChannels = [.. Prefs.MutedChannels];
            initialized = true;
        }
    }

    private void ToggleChannel(string channel, bool muted)
    {
        if (muted)
            mutedChannels.Add(channel);
        else
            mutedChannels.Remove(channel);
    }

    private async Task SavePreferences()
    {
        isSaving = true;
        message = null;
        try
        {
            var updated = new NotificationPrefs(
                emailNotifications,
                pushNotifications,
                weeklyDigest,
                mutedChannels.ToList());
            await OnSave.InvokeAsync(updated);
            message = "Preferences saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    <div class="mb-4">
        <ChangePasswordPanel OnChangePassword="OnChangePassword" />
    </div>

    <div class="mb-4">
        <h6>Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@Settings.TwoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">
                    Two-Factor Authentication
                </label>
            </div>
            @if (Settings.TwoFactorEnabled)
            {
                <span class="badge bg-success">Enabled</span>
            }
            else
            {
                <span class="badge bg-warning text-dark">Disabled</span>
            }
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @Settings.LastPasswordChange.Value.ToString("f")
            </small>
        }
    </div>

    <div class="mb-4">
