@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="security-section">
    <h4 class="mb-4">Security Settings</h4>

    <div class="mb-4">
        <ChangePasswordPanel OnChangePassword="OnChangePassword" />
    </div>

    <div class="mb-4">
        <h6>Two-Factor Authentication</h6>
        <div class="d-flex align-items-center gap-3">
            <div class="form-check form-switch">
                <input class="form-check-input" type="checkbox" id="twoFactor"
                       checked="@Settings.TwoFactorEnabled" disabled />
                <label class="form-check-label" for="twoFactor">
                    Two-Factor Authentication
                </label>
            </div>
            @if (Settings.TwoFactorEnabled)
            {
                <span class="badge bg-success">Enabled</span>
            }
            else
            {
                <span class="badge bg-warning text-dark">Disabled</span>
            }
        </div>
        @if (Settings.LastPasswordChange.HasValue)
        {
            <small class="text-muted d-block mt-2">
                Last password change: @Settings.LastPasswordChange.Value.ToString("f")
            </small>
        }
    </div>

    <div class="mb-4">
        <ActiveSessionsTable Sessions="Settings.Sessions"
                             CurrentSessionId="@CurrentSessionId"
                             OnRevokeSession="OnRevokeSession" />
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public SecurityInfo Settings { get; set; } = default!;

    [Parameter]
    public string? CurrentSessionId { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<(string CurrentPassword, string NewPassword)> OnChangePassword { get; set; }

    [Parameter, EditorRequired]
    public EventCallback<string> OnRevokeSession { get; set; }
}

@using sv_e2f0766a55f341828126b478d5ce990e.Services

<div class="appearance-section">
    <h4 class="mb-4">Appearance Settings</h4>

    <div class="row">
        <div class="col-md-6">
            <div class="mb-4">
                <h6>Theme</h6>
                @foreach (var themeOption in new[] { "Light", "Dark", "System" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="theme"
                               id="@($"theme-{themeOption}")"
                               value="@themeOption"
                               checked="@(theme == themeOption)"
                               @onchange="() => theme = themeOption" />
                        <label class="form-check-label" for="@($"theme-{themeOption}")">@themeOption</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Font Size</h6>
                @foreach (var sizeOption in new[] { "Small", "Medium", "Large" })
                {
                    <div class="form-check">
                        <input class="form-check-input" type="radio" name="fontSize"
                               id="@($"size-{sizeOption}")"
                               value="@sizeOption"
                               checked="@(fontSize == sizeOption)"
                               @onchange="() => fontSize = sizeOption" />
                        <label class="form-check-label" for="@($"size-{sizeOption}")">@sizeOption</label>
                    </div>
                }
            </div>

            <div class="mb-4">
                <h6>Language</h6>
                <select class="form-select" @bind="language">
                    <option value="en">English</option>
                    <option value="es">Español</option>
                    <option value="fr">Français</option>
                    <option value="de">Deutsch</option>
                    <option value="ja">日本語</option>
                    <option value="zh">中文</option>
                </select>
            </div>

            <div class="mb-4">
                <h6>Compact Mode</h6>
                <div class="form-check form-switch">
                    <input class="form-check-input" type="checkbox" id="compactMode" @bind="compactMode" />
                    <label class="form-check-label" for="compactMode">Enable compact mode</label>
                </div>
            </div>

            @if (!string.IsNullOrEmpty(message))
            {
                <div class="alert alert-success py-2">@message</div>
            }

            <button class="btn btn-primary" @onclick="SaveAppearance" disabled="@isSaving">
                @if (isSaving)
                {
                    <span class="spinner-border spinner-border-sm me-1"></span>
                }
                Save
            </button>
        </div>

        <div class="col-md-6">
            <h6>Live Preview</h6>
            <div class="preview-area border rounded p-3 @PreviewThemeClass"
                 style="@PreviewFontStyle">
                <div class="preview-header d-flex justify-content-between align-items-center mb-2"
                     style="@(compactMode ? "padding: 0.25rem 0;" : "padding: 0.5rem 0;")">
                    <strong>Preview Panel</strong>
                    <span class="badge @PreviewBadgeClass">@theme</span>
                </div>
                <p class="mb-2" style="@(compactMode ? "margin-bottom: 0.25rem !important;" : "")">
                    This is how your content will look with the selected settings.
                </p>
                <ul style="@(compactMode ? "margin-bottom: 0; padding-left: 1rem;" : "")">
                    <li>Theme: @theme</li>
                    <li>Font size: @fontSize</li>
                    <li>Language: @LanguageDisplayName</li>
                    <li>Compact: @(compactMode ? "On" : "Off")</li>
                </ul>
                <div class="mt-2">
                    <button class="btn btn-sm @PreviewButtonClass" disabled>Sample Button</button>
                </div>
            </div>
        </div>
    </div>
</div>

@code {
    [Parameter, EditorRequired]
    public AppearanceSettings Settings { get; set; } = default!;

    [Parameter, EditorRequired]
    public EventCallback<AppearanceSettings> OnSave { get; set; }

    private string theme = "System";
    private string fontSize = "Medium";
    private string language = "en";
    private bool compactMode;
    private string? message;
    private bool isSaving;
    private bool initialized;

    protected override void OnParametersSet()
    {
        if (!initialized && Settings is not null)
        {
            theme = Settings.Theme;
            fontSize = Settings.FontSize;
            language = Settings.Language;
            compactMode = Settings.CompactMode;
            initialized = true;
        }
    }

    private string PreviewThemeClass => theme switch
    {
        "Dark" => "bg-dark text-light",
        "Light" => "bg-white text-dark",
        _ => "bg-light text-dark"
    };

    private string PreviewBadgeClass => theme switch
    {
        "Dark" => "bg-light text-dark",
        _ => "bg-dark"
    };

    private string PreviewButtonClass => theme switch
    {
        "Dark" => "btn-outline-light",
        _ => "btn-outline-dark"
    };

    private string PreviewFontStyle => fontSize switch
    {
        "Small" => "font-size: 0.85rem;",
        "Large" => "font-size: 1.15rem;",
        _ => "font-size: 1rem;"
    };

    private string LanguageDisplayName => language switch
    {
        "en" => "English",
        "es" => "Español",
        "fr" => "Français",
        "de" => "Deutsch",
        "ja" => "日本語",
        "zh" => "中文",
        _ => language
    };

    private async Task SaveAppearance()
    {
        isSaving = true;
        message = null;
        try
        {
            var updated = new AppearanceSettings(theme, fontSize, language, compactMode);
            await OnSave.InvokeAsync(updated);
            message = "Appearance saved successfully!";
        }
        finally
        {
            isSaving = false;
        }
    }
}

