@page "/settings"
@using sv_e2f0766a55f341828126b478d5ce990e.Services
@rendermode InteractiveServer
@inject ISettingsService SettingsService

<PageTitle>Settings</PageTitle>

<div class="settings-dashboard">
    <SettingsSidebar ActiveSection="@activeSection"
                     OnSectionChanged="section => activeSection = section" />

    <div class="settings-content">
        @if (isLoading)
        {
            <div class="d-flex justify-content-center align-items-center py-5">
                <div class="spinner-border text-primary" role="status">
                    <span class="visually-hidden">Loading...</span>
                </div>
            </div>
        }
        else if (loadError is not null)
        {
            <div class="alert alert-danger">
                <strong>Error loading settings:</strong> @loadError
                <button class="btn btn-outline-danger btn-sm ms-3" @onclick="LoadDataAsync">Retry</button>
            </div>
        }
        else
        {
            @switch (activeSection)
            {
                case "Profile" when profile is not null:
                    <ProfileSection Profile="profile" OnSave="SaveProfile" />
                    break;

                case "Notifications" when notificationPrefs is not null:
                    <NotificationsSection Prefs="notificationPrefs" OnSave="SaveNotifications" />
                    break;

                case "Security" when securityInfo is not null:
                    <SecuritySection Settings="securityInfo"
                                     CurrentSessionId="@currentSessionId"
                                     OnChangePassword="HandleChangePassword"
                                     OnRevokeSession="HandleRevokeSession" />
                    break;

                case "Appearance" when appearanceSettings is not null:
                    <AppearanceSection Settings="appearanceSettings" OnSave="SaveAppearance" />
                    break;
            }
        }
    </div>
</div>

@code {
    private string activeSection = "Profile";
    private bool isLoading = true;
    private string? loadError;

    private UserProfile? profile;
    private NotificationPrefs? notificationPrefs;
    private SecurityInfo? securityInfo;
    private AppearanceSettings? appearanceSettings;

    // Assume first session is "current" for demo purposes
    private string? currentSessionId;

    protected override async Task OnInitializedAsync()
    {
        await LoadDataAsync();
    }

    private async Task LoadDataAsync()
    {
        isLoading = true;
        loadError = null;

        try
        {
            var profileTask = SettingsService.GetProfileAsync();
            var notifsTask = SettingsService.GetNotificationPrefsAsync();
            var securityTask = SettingsService.GetSecuritySettingsAsync();
            var appearanceTask = SettingsService.GetAppearanceAsync();

            await Task.WhenAll(profileTask, notifsTask, securityTask, appearanceTask);

            profile = profileTask.Result;
            notificationPrefs = notifsTask.Result;
            securityInfo = securityTask.Result;
            appearanceSettings = appearanceTask.Result;

            currentSessionId = securityInfo.Sessions.FirstOrDefault()?.Id;
        }
        catch (Exception ex)
        {
            loadError = ex.Message;
        }
        finally
        {
            isLoading = false;
        }
    }

    private async Task SaveProfile(UserProfile updated)
    {
        await SettingsService.SaveProfileAsync(updated);
        profile = updated;
    }

    private async Task SaveNotifications(NotificationPrefs updated)
    {
        await SettingsService.SaveNotificationPrefsAsync(updated);
        notificationPrefs = updated;
    }

    private async Task HandleChangePassword((string CurrentPassword, string NewPassword) args)
    {
        await SettingsService.ChangePasswordAsync(args.CurrentPassword, args.NewPassword);
        securityInfo = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task HandleRevokeSession(string sessionId)
    {
        await SettingsService.RevokeSessionAsync(sessionId);
        securityInfo = await SettingsService.GetSecuritySettingsAsync();
    }

    private async Task SaveAppearance(AppearanceSettings updated)
    {
        await SettingsService.SaveAppearanceAsync(updated);
        appearanceSettings = updated;
    }
}

